// Spanish National Holidays for 2025
// Format: YYYY-MM-DD
export const SPANISH_HOLIDAYS_2025: string[] = [
  '2025-01-01', // Año Nuevo
  '2025-01-06', // Epifanía del Señor
  '2025-04-18', // Viernes Santo
  '2025-05-01', // Fiesta del Trabajo
  '2025-08-15', // Asunción de la Virgen
  '2025-10-12', // Fiesta Nacional de España
  '2025-11-01', // Día de todos Los Santos
  '2025-12-06', // Día de la Constitución Española
  '2025-12-08', // Inmaculada Concepción
  '2025-12-25', // Natividad del Señor
];

export const STANDARD_TIMES = {
  entry: '08:00',
  stop: '14:00',
  comeback: '16:00',
  exit: '18:00',
};

export const AGOIN_LOGO_BASE64 = 'data:image/png;base64,';

export const isWorkDay = (date: Date): boolean => {
  const dayOfWeek = date.getUTCDay(); // Sunday - Saturday : 0 - 6
  if (dayOfWeek === 0 || dayOfWeek === 6) return false;
  
  const dateString = date.toISOString().split('T')[0];
  if (SPANISH_HOLIDAYS_2025.includes(dateString)) return false;
  
  return true;
};